Here each grid cell gets a DSU node. First, adjacent land cells are joined, and the DSU keeps the size of every group. For a water cell, I collect the roots of its land neighbors and add their sizes once.

This does not change the grid. The `HashSet` matters because two or more sides of the same water cell can belong to one island.

Dry run: if the neighboring roots are `{5, 8}`, and their sizes are `3` and `6`, flipping the cell gives `1 + 3 + 6 = 10`.

```java
import java.util.HashSet;

class Solution {
    private int[] parent;
    private int[] size;

    private int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    private void union(int first, int second) {
        int rootFirst = find(first);
        int rootSecond = find(second);

        if (rootFirst == rootSecond) {
            return;
        }

        if (size[rootFirst] < size[rootSecond]) {
            int temp = rootFirst;
            rootFirst = rootSecond;
            rootSecond = temp;
        }

        parent[rootSecond] = rootFirst;
        size[rootFirst] += size[rootSecond];
    }

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int totalCells = n * n;
        parent = new int[totalCells];
        size = new int[totalCells];

        for (int i = 0; i < totalCells; ++i) {
            parent[i] = i;
            size[i] = 1;
        }

        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int row = 0; row < n; ++row) {
            for (int col = 0; col < n; ++col) {
                if (grid[row][col] == 0) {
                    continue;
                }

                int current = row * n + col;
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];

                    if (nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < n &&
                        grid[nextRow][nextCol] == 1) {
                        union(current, nextRow * n + nextCol);
                    }
                }
            }
        }

        int answer = 0;
        for (int row = 0; row < n; ++row) {
            for (int col = 0; col < n; ++col) {
                if (grid[row][col] == 1) {
                    answer = Math.max(answer, size[find(row * n + col)]);
                }
            }
        }

        for (int row = 0; row < n; ++row) {
            for (int col = 0; col < n; ++col) {
                if (grid[row][col] == 1) {
                    continue;
                }

                HashSet<Integer> roots = new HashSet<>();
                for (int[] direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];

                    if (nextRow >= 0 && nextRow < n && nextCol >= 0 && nextCol < n &&
                        grid[nextRow][nextCol] == 1) {
                        roots.add(find(nextRow * n + nextCol));
                    }
                }

                int current = 1;
                for (int root : roots) {
                    current += size[root];
                }
                answer = Math.max(answer, current);
            }
        }

        return answer == 0 ? 1 : answer;
    }
}
```

Time complexity: `O(n^2 * alpha(n^2))`, which is close to `O(n^2)`.
Space complexity: `O(n^2)`.

Instead of checking every zero against island IDs, this pass lets each island add its area to the water cells touching its boundary. After all islands are processed, the best water cell already contains the sum of all distinct neighboring island areas.

Each island is visited with BFS. A set of encoded water positions prevents the same island from adding its area more than once to one water cell. The grid is changed from `1` to `-1` while marking land.

This also handles the edge cases: no land means the result is `1`, while no water means the largest island is the whole grid.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int largestIsland(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<int> waterConnection(n * n, 0);
        int largestLand = 0;
        int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int row = 0; row < n; ++row) {
            for (int col = 0; col < n; ++col) {
                if (grid[row][col] != 1) {
                    continue;
                }

                queue<pair<int, int>> cells;
                unordered_set<int> boundaryWater;
                cells.push({row, col});
                grid[row][col] = -1;
                int area = 0;

                while (!cells.empty()) {
                    auto [currentRow, currentCol] = cells.front();
                    cells.pop();
                    ++area;

                    for (auto& direction : directions) {
                        int nextRow = currentRow + direction[0];
                        int nextCol = currentCol + direction[1];

                        if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
                            continue;
                        }

                        if (grid[nextRow][nextCol] == 1) {
                            grid[nextRow][nextCol] = -1;
                            cells.push({nextRow, nextCol});
                        } else if (grid[nextRow][nextCol] == 0) {
                            boundaryWater.insert(nextRow * n + nextCol);
                        }
                    }
                }

                largestLand = max(largestLand, area);
                for (int waterCell : boundaryWater) {
                    waterConnection[waterCell] += area;
                }
            }
        }

        int answer = largestLand;
        for (int value : waterConnection) {
            answer = max(answer, value + 1);
        }

        return answer == 0 ? 1 : answer;
    }
};
```

Time complexity: `O(n^2)` because each cell and boundary is processed a constant number of times.
Space complexity: `O(n^2)` for the queue, boundary set, and water totals.

I kept the grid labels as island IDs. Starting from `2`, a DFS paints one whole island and returns its area. Later, each `0` checks its four neighbors and adds each different island only once.

The grid is changed in place, since the original `1` values become IDs. A small dry run: if a water cell touches islands `2` and `3`, with sizes `4` and `2`, its result is `1 + 4 + 2 = 7`.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution {
    int rows;
    int cols;
    int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    int paint(vector<vector<int>>& grid, int row, int col, int islandId) {
        if (row < 0 || row >= rows || col < 0 || col >= cols ||
            grid[row][col] != 1) {
            return 0;
        }

        grid[row][col] = islandId;
        int area = 1;

        for (auto& direction : directions) {
            area += paint(grid, row + direction[0], col + direction[1], islandId);
        }
        return area;
    }

public:
    int largestIsland(vector<vector<int>>& grid) {
        rows = grid.size();
        cols = grid[0].size();

        unordered_map<int, int> islandSize;
        int nextId = 2;
        int answer = 0;

        for (int row = 0; row < rows; ++row) {
            for (int col = 0; col < cols; ++col) {
                if (grid[row][col] == 1) {
                    int area = paint(grid, row, col, nextId);
                    islandSize[nextId] = area;
                    answer = max(answer, area);
                    ++nextId;
                }
            }
        }

        for (int row = 0; row < rows; ++row) {
            for (int col = 0; col < cols; ++col) {
                if (grid[row][col] != 0) {
                    continue;
                }

                unordered_set<int> seen;
                int current = 1;

                for (auto& direction : directions) {
                    int nextRow = row + direction[0];
                    int nextCol = col + direction[1];

                    if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) {
                        continue;
                    }

                    int id = grid[nextRow][nextCol];
                    if (id > 1 && seen.insert(id).second) {
                        current += islandSize[id];
                    }
                }

                answer = max(answer, current);
            }
        }

        return answer == 0 ? 1 : answer;
    }
};
```

Time complexity: `O(rows * cols)`.
Space complexity: `O(rows * cols)` for the island map and recursion stack.

This is the direct version. For every `0`, I temporarily change it to `1`, run a flood fill from that cell, and then restore the cell. It repeats work many times, but the code is short and useful for checking small grids.

A dry run on `[[1, 0], [0, 1]]`: flipping either zero connects the two diagonal cells through one new land cell, so the largest result is `3`.

The implementation restores every flipped cell, so the input grid has the same values when the method finishes.

```javascript
class Solution {
    largestIsland(grid) {
        const n = grid.length;
        const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

        const areaFrom = (startRow, startCol) => {
            const stack = [[startRow, startCol]];
            const visited = new Set();
            let area = 0;

            while (stack.length > 0) {
                const [row, col] = stack.pop();
                const key = row * n + col;

                if (visited.has(key)) {
                    continue;
                }
                visited.add(key);

                if (row < 0 || row >= n || col < 0 || col >= n || grid[row][col] === 0) {
                    continue;
                }

                area++;
                for (const [dr, dc] of directions) {
                    stack.push([row + dr, col + dc]);
                }
            }

            return area;
        };

        let answer = 0;
        let hasZero = false;

        for (let row = 0; row < n; row++) {
            for (let col = 0; col < n; col++) {
                if (grid[row][col] === 0) {
                    hasZero = true;
                    grid[row][col] = 1;
                    answer = Math.max(answer, areaFrom(row, col));
                    grid[row][col] = 0;
                }
            }
        }

        if (!hasZero) {
            return n * n;
        }
        return answer;
    }
}
```

Time complexity: `O(n^4)` in the worst case, because a flood fill can scan the whole grid for every zero.
Space complexity: `O(n^2)` for the stack and visited set.

